 61→function runChain(messages, toolCallRows, tokensByAsset = TOKENS_V1) {
 62→  const captureEvents = capture(messages);
 63→  const built = buildEvents({ snapshot: SNAPSHOT, toolCallRows, captureEvents });
 64→  const sessions = collectArtifacts({ captureEvents });
 65→  // `built` is what the provenance stage produced; `events` is the judgement.
 66→  // Keeping the names apart matters here: spreading judge()'s result over a key
 67→  // of the same name silently replaced one with the other.
 68→  return { built, ...judge({ events: built, sessions, tokensByAsset }) };
