export function outcomeOf(resultText) {
  const s = String(resultText ?? "");
  // The label is capitalised in real results — `Exit Code: 0` — while older
  // fixtures spell it `Exit code:`. Match the label case-insensitively so a
  // real result's status is read instead of silently dropped to null; without
  // this every operation looks like it has no exit status, and a timed-out
  // curl (`Exit Code: 28`, nothing else readable) is indistinguishable from a
  // call that produced nothing at all.
